```php
// routes/api.php
Route::apiResource('posts', PostController::class);
// app/Http/Controllers/PostController.php
class PostController extends Controller {
    public function index() {
        return PostResource::collection(Post::with('author')->latest()->paginate(15));
    }
    public function store(StorePostRequest $r) {
        $p = Post::create($r->validated() + ['user_id' => $r->user()->id]);
        return new PostResource($p);
    }
    public function show(Post $post) { return new PostResource($post->load('author')); }
    public function update(UpdatePostRequest $r, Post $post) {
        $this->authorize('update', $post);
        $post->update($r->validated());
        return new PostResource($post);
    }
    public function destroy(Post $post) {
        $this->authorize('delete', $post);
        $post->delete();
        return response()->noContent();
    }
}
```
apiResource (tanpa create/edit HTML) + FormRequest sahkan + Policy benarkan + Resource bentuk JSON + paginate. CRUD piawai lima kaedah.

